extends SceneTree

class Holder extends RefCounted:
	var _a: PackedInt64Array = PackedInt64Array()
	var _b: PackedInt64Array = PackedInt64Array()
	var _ids: PackedInt32Array = PackedInt32Array()
	var _flags: PackedByteArray = PackedByteArray()
	var _scalar: int = 0
	var _d: Dictionary = {}

func _initialize() -> void:
	# 1. typed builtin helpers
	var a: int = mini(3, 5)
	var b: int = maxi(3, 5)
	var c: int = clampi(9, 0, 5)
	var d: int = absi(-4)
	var e: int = signi(-9)
	print("P-a mini/maxi/clampi/absi/signi: ", a, " ", b, " ", c, " ", d, " ", e, " types ", typeof(a))
	# 2. reflection over script variables
	var h := Holder.new()
	var names: Array = []
	for p in h.get_property_list():
		if (int(p["usage"]) & PROPERTY_USAGE_SCRIPT_VARIABLE) != 0:
			names.append(p["name"])
	print("P-b script vars: ", names)
	# 3. member swap by reference, fill, duplicate
	h._a.resize(4096)
	h._b.resize(4096)
	h._a[0] = 7
	h._b[0] = 9
	var t: PackedInt64Array = h._a
	h._a = h._b
	h._b = t
	print("P-c swap: a0=", h._a[0], " b0=", h._b[0])
	# alias then element write through member
	var al: PackedInt64Array = h._a
	h._a[1] = 42
	print("P-d alias sees member write: ", al[1])
	# 4. cost
	var t0: int = Time.get_ticks_usec()
	for i in 1000:
		h._a.fill(0)
	var t1: int = Time.get_ticks_usec()
	print("P-e fill(0) 4096 x1000 us/op: ", float(t1 - t0) / 1000.0)
	t0 = Time.get_ticks_usec()
	for i in 1000:
		var cp: PackedInt64Array = h._a.duplicate()
	t1 = Time.get_ticks_usec()
	print("P-f duplicate 4096 x1000 us/op: ", float(t1 - t0) / 1000.0)
	# 5. typed dict
	var td: Dictionary[int, int] = {}
	td[5] = 9
	print("P-g typed dict get: ", td.get(5, -1), " ", td.get(6, -1))
	# 6. var_to_bytes size of nested dict
	var node_ids := PackedInt32Array()
	node_ids.resize(100)
	var payload := {"nodes": {"id": node_ids, "hp": node_ids}, "hdr": PackedInt64Array([1,2,3])}
	print("P-h var_to_bytes bytes: ", var_to_bytes(payload).size())
	# 7. packed int32 write outside range
	var p32 := PackedInt32Array([0])
	p32[0] = 3000000000
	print("P-i int32 wrap: ", p32[0])
	# 8. byte flags
	var pb := PackedByteArray([0])
	pb[0] = 300
	print("P-j byte wrap: ", pb[0])
	# 9. resize preserves/zero fills
	var rr := PackedInt64Array([5])
	rr.resize(3)
	print("P-k resize: ", rr)
	quit(0)

extends SceneTree

func _i32(n: int) -> PackedInt32Array:
	var a := PackedInt32Array()
	a.resize(n)
	return a
func _i64(n: int) -> PackedInt64Array:
	var a := PackedInt64Array()
	a.resize(n)
	return a
func _u8(n: int) -> PackedByteArray:
	var a := PackedByteArray()
	a.resize(n)
	return a

func _tlv(d: Dictionary) -> int:
	# canonical TLV size per ADR-0005 3.2: DICT tag 1 + u64 count 8 ; each key STRING 1+8+len ; PACKED 1+1+8+raw
	var n: int = 1 + 8
	for k in d:
		n += 1 + 8 + String(k).length()
		var v: Variant = d[k]
		if v is Dictionary:
			n += _tlv(v)
		elif v is PackedInt32Array:
			n += 1 + 1 + 8 + v.size() * 4
		elif v is PackedInt64Array:
			n += 1 + 1 + 8 + v.size() * 8
		elif v is int:
			n += 9
		elif v is PackedByteArray:
			n += 1 + 1 + 8 + v.size()
	return n

func build(nn: int, ne: int, np: int, nc: int, nseam: int, nsec: int, nq: int) -> Dictionary:
	var nodes := {}
	for k in ["id","section_id","def_ix","hp","hp_cap","fail_since","warn_since","mode_since","isolated_at","thaw_until","patched_at","compartment_id","port_first","req","req_max","aux_a","aux_b"]:
		nodes[k] = _i32(nn)
	for k in ["kind","flags","state","forced_mode","forced_next","mode_key","port_count","tier","subtype"]:
		nodes[k] = _u8(nn)
	nodes["stock"] = _i64(nn)
	var edges := {}
	for k in ["id","a_node","b_node","section_id","hp","hp_cap","fail_since","warn_since","mode_since","isolated_at","thaw_until","patched_at","seam_id","cap","e0","e1"]:
		edges[k] = _i32(ne)
	for k in ["kind","loop","flags","a_port","b_port","state","forced_mode","forced_next","mode_key"]:
		edges[k] = _u8(ne)
	var ports := {}
	ports["type"] = _i32(np)
	ports["cap"] = _i32(np)
	ports["local"] = _u8(np)
	ports["flags"] = _u8(np)
	var comps := {}
	for k in ["node_id","room_ref","t","t_rem","fuel_puddle","p_prev","warn_o2","warn_p","warn_t"]:
		comps[k] = _i32(nc)
	comps["n_o2"] = _i64(nc)
	comps["n_inert"] = _i64(nc)
	for k in ["band_o2","band_p","band_t","warn_bits"]:
		comps[k] = _u8(nc)
	var seams := {}
	for k in ["id","sec_a","sec_b","q","hp","leak_bp","l_seam","built_step","mode_since","edge_first","edge_count","open_first","open_count","stub_first","stub_count"]:
		seams[k] = _i32(nseam)
	for k in ["state","boundary","mode_key"]:
		seams[k] = _u8(nseam)
	seams["edge_ids"] = _i32(nseam * 6)
	seams["opening_ids"] = _i32(nseam * 2); seams["stub_ids"] = _i32(nseam * 4)
	var secs := {}
	for k in ["id","dormant_since","rate_pm","stress_pm","stress_until"]:
		secs[k] = _i32(nsec)
	for k in ["kind","flags"]:
		secs[k] = _u8(nsec)
	for k in ["vented_mgu","radiated_dj","spilled_cool_ml","produced_mgu","breathed_mgu","produced_dj","burned_uml","spilled_heat_mdj","disc_mgu","disc_cool_ml","disc_fuel_ml","disc_dj","wd_mgu","wd_cool_ml","wd_fuel_ml","wd_dj"]:
		secs[k] = _i64(nsec)
	var q := {}
	q["draw_comp"] = _i32(nq); q["draw_crew"] = _i32(nq); q["draw_mgu"] = _i64(nq)
	q["load_node"] = _i32(nq); q["load_req"] = _i32(nq)
	q["trace_kind"] = _u8(nq); q["trace_subject"] = _i32(nq); q["trace_mag"] = _i32(nq)
	q["grant_crew"] = _i32(4); q["grant_req"] = _i64(4); q["grant_got"] = _i64(4)
	var defs := {"off": _i32(60), "utf8": _u8(1500)}
	var hdr := {"next_node_id":1,"next_edge_id":1,"next_seam_id":1,"next_section_id":1,"last_step_no":1,"last_step_power":1,"last_step_atmo":1,"last_step_failure":1}
	return {"hdr": hdr, "nodes": nodes, "edges": edges, "ports": ports, "comps": comps, "seams": seams, "sections": secs, "queues": q, "defs": defs}

func _initialize() -> void:
	for cfg in [[75,100,190,10,1,2,2],[105,150,270,14,1,3,2],[120,172,300,16,2,3,4],[130,190,330,17,2,3,4]]:
		var p: Dictionary = build(cfg[0], cfg[1], cfg[2], cfg[3], cfg[4], cfg[5], cfg[6])
		print("nodes ", cfg[0], " edges ", cfg[1], " ports ", cfg[2], " tlv bytes ", _tlv(p), " var_to_bytes ", var_to_bytes(p).size())
	quit(0)
extends SceneTree

class S extends RefCounted:
	var _hp: PackedInt32Array = PackedInt32Array()

func _initialize() -> void:
	var s := S.new()
	s._hp.resize(8192)
	s._hp[0] = 5
	var snap: PackedInt32Array = s._hp.duplicate()
	s._hp[0] = 6
	print("Q-a dup isolation: snap0=", snap[0], " live0=", s._hp[0])
	# first-write cost after duplicate (COW detach) for 8192 i32 (32 KB)
	var n: int = 2000
	var t0: int = Time.get_ticks_usec()
	for i in n:
		var d: PackedInt32Array = s._hp.duplicate()
		s._hp[1] = i
	var t1: int = Time.get_ticks_usec()
	print("Q-b dup + first write (8192 i32) us/op: ", float(t1 - t0) / float(n))
	t0 = Time.get_ticks_usec()
	for i in n:
		s._hp[1] = i
	t1 = Time.get_ticks_usec()
	print("Q-c plain element write us/op: ", float(t1 - t0) / float(n))
	# payload dict with String keys: does var_to_bytes keep String keys and bytes_to_var return String
	var payload := {"a": PackedInt32Array([1,2])}
	var back: Variant = bytes_to_var(var_to_bytes(payload))
	print("Q-d key type: ", typeof((back as Dictionary).keys()[0]), " (4=String 21=StringName)")
	var payload2 := {&"a": PackedInt32Array([1,2])}
	var back2: Variant = bytes_to_var(var_to_bytes(payload2))
	print("Q-e StringName key roundtrip type: ", typeof((back2 as Dictionary).keys()[0]))
	# element loop cost over 4096 i64 with read+write via local alias
	var col := PackedInt64Array()
	col.resize(4096)
	var al: PackedInt64Array = col
	t0 = Time.get_ticks_usec()
	for r in 200:
		for i in 4096:
			al[i] = al[i] + 3
	t1 = Time.get_ticks_usec()
	print("Q-f 4096 element rmw loop us/pass: ", float(t1 - t0) / 200.0, " sum ", col[7])
	quit(0)

